const WARLOCK_ABILITY_AURA_IDS: Readonly<Record<string, string>> = {
  'Umbral Anchor': 'umbral_anchor',
  'Possess the Evil Eye': 'possess_evil_eye',
  'Hour of Judgment': 'hour_of_judgment',
  Coven: 'coven',
  'Sacrilegious March': 'sacrilegious_march',
  'Sanguine Covenant': 'dark_pact',
};

const WARLOCK_TALENT_AURA_NAMES: ReadonlySet<string> = new Set([
  'Blacktide',
  'Leaden Hex',
  'Shadow Credit',
  'Hexstorm',
  'Forbidden Reflection',
]);

// Engine auras named after the ability that opened them: the Bruin Rush Pin
// window and the Bruin Rush stun (combat/druid_engines.ts, the stun arm of
// combat/effect_dispatch.ts) and the Lunge in-flight marker
// (combat/druid_lunge.ts). Their aura ids are not ABILITIES keys, so the
// HUD's ability-name fallback never fires for them; resolve the name to the
// ability's localized name here so the buff bar and combat log never paint
// raw English in a non-English locale.
const ABILITY_NAMED_AURA_IDS: Readonly<Record<string, string>> = {
  'Bruin Rush': 'bear_charge',
  Lunge: 'lunge',
  // Thundercall's Magma Surge proc aura carries its ability's name.
  'Magma Burst': 'lava_burst',
  'Whispered Prayer': 'lesser_heal',
};

/** Aura and damage-label names the sim takes from the trinket's own item name. */
const TRINKET_NAMED_AURA_ITEM_IDS: Readonly<Record<string, string>> = {
  'Bastion Sigil': 'bastion_sigil',
  "Mender's Hourglass": 'menders_hourglass',
  'Paired Talons': 'paired_talons',
  "Hunter's Tally": 'hunters_tally',
  Stormjar: 'stormjar',
  'Echoing Lens': 'echoing_lens',
  'Sundered Prism': 'sundered_prism',
  "Duelist's Brand": 'duelists_brand',
  "Forgefather's Temper": 'forgefathers_temper',
  'Kindling Orb': 'kindling_orb',
  'Molten Fletching': 'molten_fletching',
  'Last Flame Lantern': 'last_flame_lantern',
  "Fanglord's Whistle": 'fanglords_whistle',
  'Gorgebloom Seedpod': 'gorgebloom_seedpod',
  "Foreman's Last Link": 'foremans_last_link',
  'Phial of the Tithe': 'phial_of_the_tithe',
  'Quenchwater Flask': 'quenchwater_flask',
  'Heart of the Crucible': 'heart_of_the_crucible',
  'Muster Standard': 'muster_standard',
};

export function localizeSimAuraName(name: string): string | null {
  if (name === 'Friendship') return t('referralCards.friendshipAura');
  if (name === 'Protective Charm') return t('referralCards.protectiveCharm');
  const key = AURA_NAME_KEY[name];
  if (key) return tSim(key);
  const trinketItemId = TRINKET_NAMED_AURA_ITEM_IDS[name];
  if (trinketItemId) return tEntity({ kind: 'item', id: trinketItemId, field: 'name' });
  const namedAbilityId = ABILITY_NAMED_AURA_IDS[name];
  if (namedAbilityId) return tEntity({ kind: 'ability', id: namedAbilityId, field: 'name' });
  if (name === 'Condemnation') return t('hudChrome.warlock.doomLabel');
  if (name === 'Fate Threads') return t('hudChrome.warlock.fateThreadsLabel');
  if (name === 'Soul Fragments') return t('hudChrome.procOverlay.soulFragmentsMeter');
  const abilityId = WARLOCK_ABILITY_AURA_IDS[name];
  if (abilityId) return tEntity({ kind: 'ability', id: abilityId, field: 'name' });
  if (WARLOCK_TALENT_AURA_NAMES.has(name)) return localizeTalentTitle(name);
  return null;
}

// A boss/mob "mechanic" name spliced into "{mob} unleashes {mechanic}!". Reuses the shared
// aura localizer (the mechanic names double as the debuff aura names), falling back to the
// raw English name for any mechanic not yet registered.
function locBossMechanic(name: string): string {
  return localizeSimAuraName(name) ?? name;
}

