function tArenaExtra(key: ArenaExtraKey, params?: InterpolationValues): string {
  const table = ARENA_EXTRA[getLanguage()] ?? ARENA_EXTRA.en;
  return interpolate(table[key] ?? ARENA_EXTRA.en[key], params);
}

