function tQuestExtra(key: QuestExtraKey, params?: InterpolationValues): string {
  const table = QUEST_EXTRA[getLanguage()] ?? QUEST_EXTRA.en;
  return interpolate(table[key] ?? QUEST_EXTRA.en[key], params);
}

