// Returns the localized form of a sim-emitted message, or null if not one of ours.
export function localizeSimText(text: string): string | null {
  const hearthstone = localizeHearthstoneText(text);
  if (hearthstone !== null) return hearthstone;
  if (text === 'That material selection is no longer available.')
    return t('hudChrome.materialStackSelectionUnavailable');
  const traceReaction = localizeWorldQuestTraceReaction(text);
  if (traceReaction !== null) return traceReaction;
  const exactKey = EXACT[text];
  if (exactKey) return tSim(exactKey);
  for (const rule of RULES) {
    const m = rule.re.exec(text);
    if (m) return rule.build(m);
  }
  return null;
}

export function localizeAuthoredYellText(
  text: string,
  speakerKind?: EntityKind,
  classId?: PlayerClass,
): string {
  if (speakerKind === 'player' || classId !== undefined) return text;
  return (
    localizeRiftBossYell(text) ??
    localizeWorldQuestFreightYell(text, getLanguage()) ??
    localizeSimText(text) ??
    text
  );
}

export function localizeAuthoredYellSpeakerName(
  name: string,
  speakerKind?: EntityKind,
  templateId?: string,
  classId?: PlayerClass,
): string {
  if (speakerKind === 'player' || classId !== undefined) return name;
  const freightSpeaker = worldQuestFreightSpeakerName(name, speakerKind, templateId);
  if (freightSpeaker !== null) return freightSpeaker;
  if (templateId && (speakerKind === 'mob' || speakerKind === 'npc')) {
    return tEntity({ kind: speakerKind, id: templateId, field: 'name' });
  }
  // Through the shared reverse map, not a fresh `find`: a bare find is FIRST-write
  // wins where the map is last-write wins, so on a colliding mob name the yell
  // speaker and the combat log used to disagree with each other.
  const id = mobNameToId.get(name);
  return id ? tEntity({ kind: 'mob', id, field: 'name' }) : name;
}
